                        float slope = -0.2 * aspect * step(0.0, uProgress);
                        float inclination = mix(1.0 - vUv.x + slopeDisp, vUv.x + slopeDisp, step(slope, 0.0));
                        float incProgress = fit(uProgress, 0.0, 1.0, 0.0, 1.0 + abs(slope));

